package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class UnrelatedSelectCliTest {
    @TempDir Path root;
    private record Run(int code,String out,String err) { }
    private static Run run(String... args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int code=UnrelatedSelectCli.run(args,new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8));return new Run(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    private Map<String,String> options(String output)throws Exception {Path samples=root.resolve("样本.tsv"),pairs=root.resolve("pairs.tsv");Files.writeString(samples,"sample_id\teligible\ncenter\ttrue\nleaf1\ttrue\nleaf2\ttrue\nleaf3\tfalse\nisolated\ttrue\n");Files.writeString(pairs,"sample_a\tsample_b\trelatedness\ncenter\tleaf1\t0.25\ncenter\tleaf2\t0.25\ncenter\tleaf3\t0.25\n");return new LinkedHashMap<>(Map.of("samples",samples.toString(),"pairs",pairs.toString(),"cutoff","0.125","pair-generation-cutoff","0.05","pair-coverage","complete-above-cutoff","scale","additive-grm","ties","input-order","out",root.resolve(output).toString()));}
    private static Run run(Map<String,String> options){var args=new ArrayList<String>();options.forEach((key,value)->{args.add("--"+key);args.add(value);});return run(args.toArray(String[]::new));}
    @Test void nativeSelectionRetainsSourceOrderFullDecisionsAndNamedBlockingParticipant()throws Exception {var options=options("result");Run result=run(options);assertEquals(0,result.code(),result.err());Path out=Path.of(options.get("out"));assertEquals("sample_id\nleaf1\nleaf2\nisolated\n",Files.readString(out.resolve("retained-samples.tsv")));assertEquals(List.of("isolated","leaf1","leaf2"),Files.readAllLines(out.resolve("retained-visit-order.txt")));String decisions=Files.readString(out.resolve("decisions.tsv"));assertTrue(decisions.contains("center\ttrue\t2\texcluded-related\tleaf1"));assertTrue(decisions.contains("leaf3\tfalse\t0\tineligible\t"));assertTrue(Files.readString(out.resolve("WARNINGS.md")).contains("caller assertion"));assertTrue(result.err().contains("ANALYSIS WARNINGS"));}
    @Test void eachScientificChoiceMustBeExplicit()throws Exception {var complete=options("base");for(String key:List.of("samples","pairs","cutoff","pair-generation-cutoff","pair-coverage","scale","ties")){var missing=new LinkedHashMap<>(complete);missing.remove(key);missing.put("out",root.resolve("missing-"+key).toString());Run result=run(missing);assertEquals(2,result.code(),key);assertTrue(Files.readString(Path.of(missing.get("out"),"WARNINGS.md")).contains("Required action:"));assertFalse(Files.exists(Path.of(missing.get("out"),"results.json")));}}
    @Test void alreadySparserGraphAndWrongScaleAreRejected()throws Exception {for(String[] bad:List.of(new String[]{"pair-generation-cutoff","0.2"},new String[]{"scale","king-kinship"},new String[]{"pair-coverage","infer"},new String[]{"ties","infer"})){var options=options("bad-"+bad[0]);options.put(bad[0],bad[1]);assertEquals(2,run(options).code());assertFalse(Files.exists(Path.of(options.get("out"),"results.json")));}}
    @Test void duplicateSelfAndUnknownPairsFailWithRetainedSources()throws Exception {for(String rows:List.of("center\tleaf1\t.3\nleaf1\tcenter\t.2\n","center\tcenter\t.3\n","center\tunknown\t.3\n")){var options=options("bad-"+UUID.randomUUID());Files.writeString(Path.of(options.get("pairs")),"sample_a\tsample_b\trelatedness\n"+rows);assertEquals(2,run(options).code());Path out=Path.of(options.get("out"));assertTrue(Files.isRegularFile(out.resolve("partial/pairs.tsv")));assertTrue(Files.readString(out.resolve("analysis-status.json")).contains("failed"));assertFalse(Files.exists(out.resolve("retained-samples.tsv")));}}
    @Test void emptyEligibleCohortIsRetainedWithProminentReviewWarning()throws Exception {var options=options("empty");Path samples=Path.of(options.get("samples"));Files.writeString(samples,Files.readString(samples).replace("true","false"));assertEquals(0,run(options).code());Path out=Path.of(options.get("out"));assertEquals("sample_id\n",Files.readString(out.resolve("retained-samples.tsv")));assertTrue(Files.readString(out.resolve("WARNINGS.md")).contains("EMPTY ELIGIBLE COHORT"));}
    @Test void unicodeOptionsAndExistingOutputArePreserved()throws Exception {var options=options("输出");Path carrier=root.resolve("options.json");Files.writeString(carrier,RegenieRuntime.json(options));assertEquals(0,run("--options-file",carrier.toString()).code());Path out=Path.of(options.get("out"));Files.writeString(out.resolve("keep"),"preserved");assertEquals(2,run(options).code());assertEquals("preserved",Files.readString(out.resolve("keep")));assertTrue(run("--help").out().contains("maximal independent set"));assertEquals(2,run("--out","a","--out","b").code());}
    @Test void fiveHundredIndependentPythonGraphsAndExhaustiveCounterexampleMatchEveryDecision()throws Exception {
        Path file=Path.of(Objects.requireNonNull(getClass().getResource("/unrelated-selection/references.json")).toURI());Map<?,?> record=(Map<?,?>)SimpleJson.parse(Files.readString(file));List<?> cases=(List<?>)record.get("cases");assertEquals(501,cases.size());for(Object item:cases){Map<?,?> row=(Map<?,?>)item;var ids=new ArrayList<String>();for(Object id:(List<?>)row.get("samples"))ids.add((String)id);var eligible=new HashSet<String>();for(Object id:(List<?>)row.get("eligible"))eligible.add((String)id);var pairs=new ArrayList<org.jlinalg.genetics.RelatedSampleSelection.Pair>();for(Object pair:(List<?>)row.get("pairs")){List<?> values=(List<?>)pair;pairs.add(new org.jlinalg.genetics.RelatedSampleSelection.Pair((String)values.get(0),(String)values.get(1),((Number)values.get(2)).doubleValue()));}var actual=org.jlinalg.genetics.RelatedSampleSelection.select(ids,eligible,pairs,((Number)row.get("cutoff")).doubleValue(),org.jlinalg.genetics.RelatedSampleSelection.TiePolicy.valueOf((String)row.get("ties")));Map<?,?> expected=(Map<?,?>)row.get("expected");assertEquals(expected.get("retained"),actual.retained(),String.valueOf(row.get("case")));assertEquals(((Number)expected.get("supplied_pairs")).intValue(),actual.suppliedPairs());assertEquals(((Number)expected.get("threshold_pairs")).intValue(),actual.thresholdPairs());assertEquals(((Number)expected.get("eligible_threshold_pairs")).intValue(),actual.eligibleThresholdPairs());List<?> decisions=(List<?>)expected.get("decisions");assertEquals(decisions.size(),actual.decisions().size());for(int i=0;i<decisions.size();i++){Map<?,?> wanted=(Map<?,?>)decisions.get(i);var found=actual.decisions().get(i);assertEquals(wanted.get("sample_id"),found.sampleId());assertEquals(wanted.get("eligible"),found.eligible());assertEquals(((Number)wanted.get("initial_degree")).intValue(),found.initialDegree());assertEquals(wanted.get("status"),found.status());assertEquals(wanted.get("excluded_by"),found.excludedBy());}if(row.containsKey("exhaustive_maximum_size"))assertTrue(actual.retained().size()<((Number)row.get("exhaustive_maximum_size")).intValue());}
    }
}
